      "mainEntity": [
        {
          "@type": "Question",
          "name": "What standards can documentation support?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS uses documented handling practices that support NIST SP 800-88 media sanitization guidance and can provide records relevant to HIPAA, FERPA, GLBA, and other organizational requirements. Project documentation varies by equipment type, destruction method, and requested reporting."
          }
        },
        {
          "@type": "Question",
          "name": "Is pickup available in Bakersfield?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS Electronic Recycling coordinates scheduled pickup for qualifying business, institutional, and commercial volumes throughout Bakersfield and Kern County. Organizations can provide equipment categories, estimated quantities, access needs, and timing so STS can evaluate an appropriate collection plan."
          }
        },
        {
          "@type": "Question",
          "name": "What happens after equipment is collected?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Equipment is documented, transported, and evaluated for reuse, data destruction, component recovery, or material recycling. Chain-of-custody records help establish a clear handling trail from pickup through final processing and requested project reporting."
          }
        },
        {
          "@type": "Question",
          "name": "Can STS support large technology refreshes?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. STS can coordinate projects involving workstations, servers, networking hardware, monitors, printers, and mixed office electronics. Planning begins with asset volume, site access, scheduling constraints, and any documentation or data handling requirements."
          }
        }
      ]
